package com.wanyuecity.energy.system.audit;
import com.fasterxml.jackson.databind.ObjectMapper;import com.wanyuecity.energy.system.service.AuditLogService;import jakarta.servlet.*;import jakarta.servlet.http.*;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.security.core.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.*;import java.util.regex.*;
@Slf4j @RequiredArgsConstructor public class AuditMutationFilter extends OncePerRequestFilter{
 private static final Set<String> MUTATING=Set.of("POST","PUT","PATCH","DELETE");private static final Pattern ID=Pattern.compile("/(\\d+)(?:/|$)");private final AuditLogService service;private final ObjectMapper json;
 @Override protected boolean shouldNotFilter(HttpServletRequest r){return !MUTATING.contains(r.getMethod())||r.getRequestURI().equals("/auth/login");}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{long started=System.currentTimeMillis();Exception error=null;try{chain.doFilter(req,res);}catch(ServletException|IOException|RuntimeException e){error=e;throw e;}finally{try{Authentication a=SecurityContextHolder.getContext().getAuthentication();String operator=a!=null&&a.isAuthenticated()&&!"anonymousUser".equals(a.getPrincipal())?a.getName():req.getRequestURI().contains("/verification/tasks/")?"FIELD_VERIFICATION_LINK":"anonymous";String path=sanitize(req.getRequestURI());String type=businessType(path);Matcher m=ID.matcher(path);String id=m.find()?m.group(1):null;Map<String,Object> result=new LinkedHashMap<>();result.put("httpStatus",res.getStatus());result.put("success",error==null&&res.getStatus()<400);result.put("durationMs",System.currentTimeMillis()-started);if(error!=null)result.put("errorType",error.getClass().getSimpleName());service.record(operator,null,req.getMethod()+" "+path,type,id,null,json.writeValueAsString(result),ip(req),req.getHeader("User-Agent"));}catch(Exception auditError){log.error("audit persistence failed: {}",auditError.getClass().getSimpleName());}}}
 private String sanitize(String p){return p.replaceAll("(/api/v1/verification/tasks/)[^/]+","$1{token}");}private String businessType(String p){String prefix="/api/v1/";if(p.startsWith(prefix)){String x=p.substring(prefix.length());int slash=x.indexOf('/');return (slash<0?x:x.substring(0,slash)).toUpperCase().replace('-','_');}return p.startsWith("/auth")?"AUTH":"SYSTEM";}private String ip(HttpServletRequest r){String x=r.getHeader("X-Forwarded-For");return x==null||x.isBlank()?r.getRemoteAddr():x.split(",")[0].trim();}
}
